import { useEffect, useState } from "react";
import type { HTMLAttributes, ReactNode, Ref } from "react";
import "./Avatar.css";

type AvatarSize = "small" | "medium" | "large";

/* `role` and `aria-label` are Omitted, not merely undocumented: the component DERIVES both from
   `src`/`alt` (image → the <img> carries the semantics; initials → `role="img"` + the alt as the
   name; empty alt → hidden). They are written after `{...props}`, and an explicit `undefined` BEATS
   a spread value — so leaving them in the surface silently dropped whatever a consumer passed
   whenever an image was showing. Omitting says so in the type instead of failing at runtime. */
export interface AvatarProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "className" | "children" | "role" | "aria-label"> {
  /**
   * Avatar size.
   *
   * @default "medium"
   */
  size?: AvatarSize;
  src?: string;
  alt: string;
  children?: ReactNode;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function Avatar({
  size = "medium",
  src,
  alt,
  children,
  className,
  ...props
}: AvatarProps) {
  const [hasImageError, setHasImageError] = useState(false);
  const shouldShowImage = Boolean(src) && !hasImageError;
  // An empty alt marks the avatar as decorative (its meaning is carried by adjacent text):
  // present it as an unnamed `img` would fail role-img-alt, so hide it from AT instead.
  const isDecorative = !alt;

  useEffect(() => {
    setHasImageError(false);
  }, [src]);

  return (
    <div
      {...props}
      role={shouldShowImage || isDecorative ? undefined : "img"}
      aria-label={shouldShowImage || isDecorative ? undefined : alt}
      aria-hidden={!shouldShowImage && isDecorative ? true : undefined}
      data-size={size}
      className={
        className
          ? `sd-avatar sd-type-label-medium ${className}`
          : "sd-avatar sd-type-label-medium"
      }
    >
      {shouldShowImage ? (
        <img
          src={src}
          alt={alt}
          className="sd-avatar__image"
          onError={() => setHasImageError(true)}
        />
      ) : (
        <span aria-hidden={alt ? undefined : true} className="sd-avatar__fallback">
          {children}
        </span>
      )}
    </div>
  );
}

.sd-avatar {
  display: inline-flex;
  /* A glyph centred in its own box (naming-convention.md, a glyph in a painted box): the inset is for
     text on a line, and here it would only shrink the box an image or initials fill. */
  padding-inline: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex: 0 0 auto;
  background: var(--sd-avatar-background);
  color: var(--sd-avatar-foreground);
  border: var(--sd-avatar-border-width) solid var(--sd-avatar-border);
  border-radius: var(--sd-avatar-radius);
  corner-shape: round;
  user-select: none;
}

.sd-avatar[data-size="small"] {
  width: var(--sd-avatar-size-small);
  height: var(--sd-avatar-size-small);
  font-size: var(--sd-avatar-font-size-small);
}

.sd-avatar[data-size="medium"] {
  width: var(--sd-avatar-size-medium);
  height: var(--sd-avatar-size-medium);
  font-size: var(--sd-avatar-font-size-medium);
}

.sd-avatar[data-size="large"] {
  width: var(--sd-avatar-size-large);
  height: var(--sd-avatar-size-large);
  font-size: var(--sd-avatar-font-size-large);
}

.sd-avatar__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sd-avatar__fallback {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}
